// Reproducible acceptance receipts; artifacts are generated by the adjacent
// production scenarios and node:test/Bun runs, never by a copied dial.
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
const dir = process.env.T2F13_EVIDENCE; assert.ok(dir);
const sha = s => createHash('sha256').update(s).digest('hex');
const json = name => JSON.parse(readFileSync(join(dir, name), 'utf8'));
const sinkHashes = {}; const behaviorHashes = {}; const matrix = [];
for (const engine of ['node', 'bun']) {
  const base = json(`sinks-base-${engine}.json`); const final = json(`sinks-final-${engine}.json`);
  assert.equal(Object.keys(base).length, 8);
  sinkHashes[engine] = {};
  for (const sink of Object.keys(base)) {
    assert.equal(final[sink], base[sink], `${engine} ${sink} bytes`);
    sinkHashes[engine][sink] = [sha(base[sink]), sha(final[sink])];
  }
  const before = json(`wire-base-${engine}.json`); const after = json(`wire-final-${engine}.json`);
  behaviorHashes[engine] = {};
  for (const part of ['wire', 'logs', 'failures']) {
    assert.deepEqual(after[part], before[part], `${engine} ${part}`);
    behaviorHashes[engine][part] = [sha(JSON.stringify(before[part])), sha(JSON.stringify(after[part]))];
  }
  assert.equal(before.raw.length, 8); assert.equal(after.raw.length, 8);
  const fresh = new Set();
  for (let i = 0; i < before.raw.length; i++) {
    const a = before.raw[i].bytes, b = after.raw[i].bytes;
    const key = /^Sec-WebSocket-Key: ([^\r]+)\r$/im;
    for (const bytes of [a, b]) {
      const value = bytes.match(key)[1], decoded = Buffer.from(value, 'base64');
      assert.equal(decoded.length, 16); assert.equal(decoded.toString('base64'), value);
      assert.ok(!fresh.has(value), 'fresh random handshake key on every dial'); fresh.add(value);
    }
    assert.equal(before.raw[i].preResponse, ''); assert.equal(after.raw[i].preResponse, '');
    const onlyValue = /^(Sec-WebSocket-Key: )[^\r]+/im;
    assert.equal(a.replace(onlyValue, '$1<RANDOM-HANDSHAKE-KEY>'), b.replace(onlyValue, '$1<RANDOM-HANDSHAKE-KEY>'), 'only random handshake key VALUE may differ');
  }
  function outcomes(phase) {
    const text = readFileSync(join(dir, `${phase}-credentials-${engine}-wrapper.log`), 'utf8');
    const results = new Map();
    const regex = engine === 'node' ? /^(not )?ok \d+ - (.*)$/gm : /^\((pass|fail)\) (.*?)(?: \[[^\]\n]+\])?$/gm;
    for (const match of text.matchAll(regex)) results.set(match[2], engine === 'node' ? !match[1] : match[1] === 'pass');
    return results;
  }
  const baseline = outcomes('baseline'), changed = outcomes('final');
  assert.equal(baseline.size, 86); assert.equal(changed.size, baseline.size);
  for (const [name, pass] of baseline) {
    assert.equal(changed.get(name), true, `${engine} final ${name}`);
    const control = name.startsWith('control:');
    assert.equal(pass, control, `${engine}: controls pass on base; new behavior fails on base: ${name}`);
    matrix.push({ engine, name, classification: control ? 'control' : 'red-then-green', baseline: pass ? 'PASS' : 'FAIL', final: 'PASS' });
  }
}
const baseCommit = '4976c67d5c7916a15046c627b68913994c33b3cb';
const diff = execFileSync('git', ['diff', '--numstat', `${baseCommit}..HEAD`], { encoding: 'utf8' }).trim();
let production = 0, test = 0, docs = 0;
for (const line of diff.split('\n')) {
  const [added, removed, path] = line.split('\t');
  const size = Number(added) - Number(removed);
  if (['src/mcpl/types.ts', 'src/mcpl/transport.ts', 'src/mcpl/protocol-family.ts'].includes(path)) production += size;
  else if (path === 'README.md') docs += size;
  else { assert.ok(path.startsWith('test/'), `out-of-scope ${path}`); test += size; }
}
assert.ok(production <= 300);
const lockHash = sha(readFileSync('package-lock.json'));
assert.equal(lockHash, sha(readFileSync(join(dir, 'package-lock.json'))));
const report = { sinkHashes, behaviorHashes, matrix, production, test, docs, lockHash };
writeFileSync(join(dir, 'acceptance.json'), JSON.stringify(report, null, 2));
console.log(JSON.stringify({ sinkHashes, behaviorHashes, counts: { control: matrix.filter(t => t.classification === 'control').length / 2,
  redThenGreen: matrix.filter(t => t.classification !== 'control').length / 2 }, production, test, docs, lockHash }, null, 2));
console.log('B: all eight sink pairs match on both engines. C: failure/log pairs match; wire differs only in random handshake keys. E: per-test matrix saved.');
